/// What `print(_:)` writes for `items`, without the newline.
private func printed(_ items: Any...) -> String {
    items.map { String(describing: $0) }.joined(separator: " ")
}

// Sources/SimulationModule/ScheduleLabel.swift:10
fileprivate extension ScheduleLabel {
    static let autosave = ScheduleLabel("Autosave")
}

// Sources/SimulationModule/SimulationModule.docc/SimulationModule.md:20
fileprivate struct Position: Component { var x: Double }

fileprivate struct Velocity: Component { var dx: Double }

fileprivate struct FixedSteps: Resource { var count = 0 }

fileprivate enum GameState: States { case menu, playing, paused }

/// Moves each entity by its velocity over one fixed timestep.
@System
fileprivate struct Physics {
    func run(_ movers: Update<Position>.Over<Velocity>, _ fixedTime: ResourceReader<FixedTime>) {
        let seconds = fixedTime.value.timestep / .seconds(1)
        movers { position, row in
            position.x += row.components.dx * seconds
        }
    }
}

/// Counts the runs of the schedule it is in.
@System
fileprivate struct CountSteps {
    func run(_ steps: ResourceWriter<FixedSteps>) {
        steps.value.count += 1
    }
}

/// Spawns a ball at the origin.
@System
fileprivate struct SpawnBall {
    func run(commands: inout Commands) {
        commands.spawn(Position(x: 0), Velocity(dx: 64))
    }
}

